/**
 * Unit tests for ParserMinimalBase#getValueAsString
 */
public class ParserMinimalBase_getValueAsString_TriageGen0Test {

    private ParserMinimalBase parser;

    @Before
    public void setUp() {
        // ParserMinimalBase is an abstract class, so we must mock it or use a spy
        parser = Mockito.mock(ParserMinimalBase.class, Mockito.withSettings().useConstructor().defaultAnswer(Mockito.CALLS_REAL_METHODS));
    }

    @Test
    public void testGetValueAsString_WhenTokenIsValueString() throws IOException {
        // Arrange
        String expectedText = "hello world";
        String defaultValue = "default";

        // We need to simulate the internal state _currToken. 
        // Since _currToken is likely protected/private, we rely on the fact that 
        // we are testing the logic of the method provided.
        // In a real scenario, we'd use a concrete subclass or reflection if needed, 
        // but since we are mocking the real methods of the abstract class:

        when(parser.getCurrentToken()).thenReturn(JsonToken.VALUE_STRING);
        // Note: The method uses _currToken directly. In Mockito, we can't easily set private fields 
        // without reflection, but since the prompt provides the method source, 
        // we assume the test environment allows setting the state or we mock the behavior.
        // However, since the method logic depends on the field _currToken, 
        // we will simulate the logic via a Spy on a concrete implementation or use Reflection.

        // Using reflection to set the private field _currToken for maximum coverage
        setInternalState(parser, "_currToken", JsonToken.VALUE_STRING);
        when(parser.getText()).thenReturn(expectedText);

        // Act
        String result = parser.getValueAsString(defaultValue);

        // Assert
        assertEquals(expectedText, result);
        verify(parser).getText();
    }

    @Test
    public void testGetValueAsString_WhenTokenIsNull() throws IOException {
        // Arrange
        String defaultValue = "default";
        setInternalState(parser, "_currToken", null);

        // Act
        String result = parser.getValueAsString(defaultValue);

        // Assert
        assertEquals(defaultValue, result);
    }

    @Test
    public void testGetValueAsString_WhenTokenIsValueNull() throws IOException {
        // Arrange
        String defaultValue = "default";
        setInternalState(parser, "_currToken", JsonToken.VALUE_NULL);

        // Act
        String result = parser.getValueAsString(defaultValue);

        // Assert
        assertEquals(defaultValue, result);
    }

    @Test
    public void testGetValueAsString_WhenTokenIsNotScalarValue() throws IOException {
        // Arrange
        String defaultValue = "default";
        // START_OBJECT is not a scalar value
        setInternalState(parser, "_currToken", JsonToken.START_OBJECT);

        // Act
        String result = parser.getValueAsString(defaultValue);

        // Assert
        assertEquals(defaultValue, result);
    }

    @Test
    public void testGetValueAsString_WhenTokenIsScalarButNotString() throws IOException {
        // Arrange
        String expectedText = "123";
        String defaultValue = "default";
        // VALUE_NUMBER_INT is a scalar value
        setInternalState(parser, "_currToken", JsonToken.VALUE_NUMBER_INT);
        when(parser.getText()).thenReturn(expectedText);

        // Act
        String result = parser.getValueAsString(defaultValue);

        // Assert
        assertEquals(expectedText, result);
    }

    /**
     * Helper method to set private fields in the parser for testing purposes.
     */
    private void setInternalState(Object target, String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(target, value);
        } catch (Exception e) {
            // If field is in the parent class (ParserMinimalBase)
            try {
                java.lang.reflect.Field field = ParserMinimalBase.class.getDeclaredField(fieldName);
                field.setAccessible(true);
                field.set(target, value);
            } catch (Exception ex) {
                throw new RuntimeException("Failed to set field " + fieldName, ex);
            }
        }
    }
}
